live as (
  select p.proname as name, md5(p.prosrc) as body_md5, p.prosecdef as security_definer,
         coalesce(array_to_string(p.proconfig, ' '), '') as config,
         has_function_privilege('anon', p.oid, 'EXECUTE') as anon_exec,
         has_function_privilege('authenticated', p.oid, 'EXECUTE') as authenticated_exec
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname in ('public', 'audit')
)
select l.name,
       coalesce(max(e.source), 'NO MATCH') as live_version_from,
       l.security_definer, l.anon_exec, l.authenticated_exec, l.config
from live l
left join expected e on e.name = l.name and e.body_md5 = l.body_md5
where l.name in (select name from expected)
group by l.name, l.body_md5, l.security_definer, l.anon_exec, l.authenticated_exec, l.config
order by (coalesce(max(e.source), 'NO MATCH') = 'NO MATCH') desc, l.name;
